/**
 * C11 — legacy `.html.md` URL preservation.
 *
 * The old hand-written site published 18 markdown twins:
 *
 *   dist/posts/<slug>.html.md   x16   one per article
 *   dist/index.html.md               homepage mirror
 *   dist/about.html.md               about mirror
 *
 * These URLs are already indexed and linked from outside, so the generated bytes must
 * match the historical files exactly. That is why the front matter is *regenerated* in
 * one fixed field order (Author, Published, Updated, Slug, Tags, Canonical URL) instead
 * of being copied out of the source `.md`, and why every slug is derived from the
 * `canonicalPath` front-matter field rather than from `entry.id`.
 *
 * Why the sources are read with `node:fs` instead of `getCollection('articles')`:
 * `astro:content` is a Vite virtual module, and an integration hook module is loaded by
 * Node through the bundled config — importing `astro:content` here would make the
 * config unresolvable. Reading `src/content/articles/*.md` directly has no such coupling.
 *
 * The twins are deliberately NOT sitemap entries (the `sitemap()` filter in
 * `astro.config.mjs` drops `*.md`); articles advertise them with
 * `<link rel="alternate" type="text/markdown">` instead.
 */
import { mkdir, readdir, readFile, writeFile } from "node:fs/promises";

import type { AstroIntegration } from "astro";

import { identity } from "../data/identity";
import { links, SITE_URL } from "../data/links";

const ARTICLES_DIR = new URL("../content/articles/", import.meta.url);
const EXPECTED_ARTICLES = 16;

/**
 * `identity.location` is "Argentina"; the twin prose needs the demonym. The data file
 * exposes only the country name, so the adjective is pinned here to keep the sentence
 * grammatical without editing C15.
 */
const DEMONYM = "Argentine";

/**
 * Curated order of the homepage's "Canonical article slugs" list. This is presentation
 * order, not publish-date order — it is preserved verbatim from the historical
 * `index.html.md`, so it cannot be derived and is pinned here. The emitter throws if a
 * slug is missing from the collection or if the collection holds a slug not listed here.
 */
const HOMEPAGE_ARTICLE_ORDER: readonly string[] = [
  "linsaftw-persona-builder-operator-infrastructure-founder",
  "minecraft-server-security-starts-at-the-edge",
  "minecraft-plugin-compatibility-is-product-quality",
  "folia-support-is-a-threading-discipline",
  "packetevents-anticheat-proof-over-vibes",
  "velocity-bungeecord-and-proxy-trust-boundaries",
  "builtbybit-creators-need-support-operations",
  "arkflame-product-ecosystem-for-minecraft-infrastructure",
  "ai-coding-agents-for-minecraft-plugin-development",
  "minecraft-performance-work-is-customer-support",
  "linsaftw-minecraft-infrastructure-from-argentina",
  "flamecord-and-the-proxy-layer",
  "exploitfixer-and-packet-security",
  "arkflame-studios-main-hub",
  "ai-assisted-coding-needs-standards",
  "developer-health-and-output",
];

/**
 * C4 — retired claims that must appear nowhere in shipped output. Checked against every
 * generated twin so a future copy edit cannot quietly reintroduce one.
 */
const BANNED_PATTERNS: readonly RegExp[] = [
  /\b2015\b/,
  /2023\s+VeloFlame/i,
  /2023 Velocity expansion/i,
  /2024 FairPlay/i,
  /2024 AI systems/i,
  /\bCEO\b/,
  /hello_world\.java/,
  /Created LinsaFTW/i,
  /2025 Top Creator/i,
];

interface Article {
  readonly slug: string;
  readonly title: string;
  readonly description: string;
  readonly author: string;
  readonly published: string;
  readonly updated: string;
  readonly tags: readonly string[];
  readonly canonicalPath: string;
  readonly body: string;
}

/**
 * Strict reader for the C14 front-matter subset: `key: scalar` / `key: "json string"` /
 * `key: ["json", "array"]` / `key: true|false`. Anything else (nested maps, block
 * scalars, folded values) throws rather than being guessed at — a legacy twin must be
 * byte-exact, so a malformed source has to stop the build instead of emitting a
 * plausible-looking file.
 */
function parseFrontMatter(
  source: string,
  file: string,
): { fields: Record<string, string | string[] | boolean>; body: string } {
  const match = /^---\n([\s\S]*?)\n---\n/.exec(source);
  if (!match) {
    throw new Error(`emitMarkdownTwins: ${file} has no parseable front matter block.`);
  }

  const fields: Record<string, string | string[] | boolean> = {};
  for (const line of match[1].split("\n")) {
    const field = /^([A-Za-z][A-Za-z0-9_-]*):\s*(.*)$/.exec(line);
    if (!field) {
      throw new Error(
        `emitMarkdownTwins: ${file} has an unsupported front-matter line: ${JSON.stringify(line)}`,
      );
    }
    const key = field[1];
    const raw = field[2];
    if (raw.startsWith('"') || raw.startsWith("[")) {
      fields[key] = JSON.parse(raw);
    } else if (raw === "true" || raw === "false") {
      fields[key] = raw === "true";
    } else {
      fields[key] = raw;
    }
  }

  // C14: the source body starts with one blank line after the closing `---`. The twins
  // supply their own separating blank line, so drop exactly that one newline.
  return { fields, body: source.slice(match[0].length).replace(/^\n/, "") };
}

function requiredString(fields: Record<string, unknown>, key: string, file: string): string {
  const value = fields[key];
  if (typeof value !== "string" || value.length === 0) {
    throw new Error(`emitMarkdownTwins: ${file} is missing string front-matter field "${key}".`);
  }
  return value;
}

/** UTC `YYYY-MM-DD`, so a local-time build can never shift a day. */
function isoDay(value: string, key: string, file: string): string {
  const stamp = Date.parse(value);
  if (Number.isNaN(stamp)) {
    throw new Error(`emitMarkdownTwins: ${file} has an unparseable "${key}" date: ${value}`);
  }
  return new Date(stamp).toISOString().slice(0, 10);
}

/** `/posts/<slug>.html` -> `<slug>`. Never `entry.id`, so collection-id changes are inert. */
function slugFromCanonicalPath(canonicalPath: string, file: string): string {
  const match = /^\/posts\/([^/]+)\.html$/.exec(canonicalPath);
  if (!match) {
    throw new Error(
      `emitMarkdownTwins: ${file} canonicalPath is not /posts/<slug>.html: ${canonicalPath}`,
    );
  }
  return match[1];
}

export function parseArticle(fileName: string, source: string): Article {
  const file = `src/content/articles/${fileName}`;
  const { fields, body } = parseFrontMatter(source, file);

  const tags = fields.tags;
  if (!Array.isArray(tags) || tags.some((tag) => typeof tag !== "string")) {
    throw new Error(`emitMarkdownTwins: ${file} "tags" must be an array of strings.`);
  }

  const canonicalPath = requiredString(fields, "canonicalPath", file);
  if (body.length === 0) {
    throw new Error(`emitMarkdownTwins: ${file} has an empty body.`);
  }

  return {
    slug: slugFromCanonicalPath(canonicalPath, file),
    title: requiredString(fields, "title", file),
    description: requiredString(fields, "description", file),
    author: requiredString(fields, "author", file),
    published: isoDay(requiredString(fields, "publishedAt", file), "publishedAt", file),
    updated: isoDay(requiredString(fields, "updatedAt", file), "updatedAt", file),
    tags,
    canonicalPath,
    body,
  };
}

/** Byte-exact reconstruction of the historical `posts/<slug>.html.md`. */
export function renderArticleTwin(article: Article): string {
  return [
    `# ${article.title}`,
    "",
    `> ${article.description}`,
    "",
    `- Author: ${article.author}`,
    `- Published: ${article.published}`,
    `- Updated: ${article.updated}`,
    `- Slug: ${article.slug}`,
    `- Tags: ${article.tags.join(", ")}`,
    `- Canonical URL: ${SITE_URL}${article.canonicalPath}`,
    "",
    article.body,
  ].join("\n");
}

export function renderHomepageTwin(articles: readonly Article[]): string {
  const bySlug = new Map(articles.map((article) => [article.slug, article]));

  return [
    `# ${identity.handle} — Minecraft Infrastructure Developer`,
    "",
    `> ${identity.name}, known as ${identity.handle}, is an ${DEMONYM} Minecraft infrastructure developer and founder of ${identity.founderOf}.`,
    "",
    `${identity.handle} builds Minecraft server software, Java plugins, proxy security tools, anti-exploit systems, anticheat systems, performance tooling, and product infrastructure under ${identity.founderOf}.`,
    "",
    "## Persona analysis",
    "",
    "- Builder: hands-on Java, Bukkit, Spigot, Paper, Folia, Velocity, BungeeCord, and PacketEvents work.",
    "- Operator: focused on uptime, logs, compatibility, support, profiling, and production server failure modes.",
    `- Founder: uses ${identity.founderOf} as the business and product ecosystem around the technical work.`,
    "",
    "## Canonical article slugs",
    "",
    ...HOMEPAGE_ARTICLE_ORDER.map((slug) => {
      const article = bySlug.get(slug);
      if (!article) {
        throw new Error(
          `emitMarkdownTwins: homepage twin references "${slug}", which is not in the collection.`,
        );
      }
      return `- [${article.title}](${SITE_URL}${article.canonicalPath}): ${article.description}`;
    }),
    "",
  ].join("\n");
}

export function renderAboutTwin(): string {
  return [
    `# About ${identity.handle}`,
    "",
    `> About ${identity.name}, known as ${identity.handle}, founder of ${identity.founderOf}.`,
    "",
    `${identity.handle} is the public handle of ${identity.name}. ${identity.founderOf} is the product ecosystem for Minecraft server infrastructure work.`,
    "",
    "## Technical focus",
    "",
    "- Minecraft server infrastructure",
    "- Java plugin engineering",
    "- Bukkit, Spigot, Paper, Folia compatibility",
    "- BungeeCord, Waterfall, Velocity, and proxy security",
    "- Packet exploit protection",
    "- Anticheat systems",
    "- Performance tooling",
    "- Server-owner support and product operations",
    "",
    "## Persona analysis",
    "",
    `${identity.handle} should be interpreted as a builder/operator/founder persona: direct technical output, real server operations, security-first product development, marketplace support, and long-term infrastructure quality.`,
    "",
    "## Official links",
    "",
    `- [${identity.handle} homepage](${SITE_URL}/): Canonical profile.`,
    `- [${identity.founderOf}](${links.arkflame}): Product ecosystem.`,
    `- [${identity.handle} GitHub](${links.github}): Developer profile.`,
    `- [ArkFlame GitHub](${links.githubOrg}): Organization profile.`,
    "",
  ].join("\n");
}

function assertNoBannedClaims(twins: ReadonlyMap<string, string>): void {
  for (const [file, contents] of twins) {
    for (const pattern of BANNED_PATTERNS) {
      if (pattern.test(contents)) {
        throw new Error(
          `emitMarkdownTwins: refusing to write ${file} — it matches C4 banned pattern ${pattern}`,
        );
      }
    }
  }
}

export default function emitMarkdownTwins(): AstroIntegration {
  return {
    name: "linsaftw-emit-markdown-twins",
    hooks: {
      // Astro 7 has no per-integration `order` field for build hooks (the only `order`
      // in integrations.d.ts belongs to `addMiddleware`), so registration order is hook
      // order. Registered last, after `sitemap()` and the sitemap flattener.
      "astro:build:done": async ({ dir, logger }) => {
        const files = (await readdir(ARTICLES_DIR)).filter((name) => name.endsWith(".md")).sort();
        if (files.length !== EXPECTED_ARTICLES) {
          throw new Error(
            `emitMarkdownTwins: expected ${EXPECTED_ARTICLES} articles, found ${files.length} in ${ARTICLES_DIR.pathname}`,
          );
        }

        const articles = await Promise.all(
          files.map(async (name) =>
            parseArticle(name, await readFile(new URL(name, ARTICLES_DIR), "utf8")),
          ),
        );

        await mkdir(new URL("./posts/", dir), { recursive: true });

        const twins = new Map<string, string>();
        for (const article of articles) {
          twins.set(`posts/${article.slug}.html.md`, renderArticleTwin(article));
        }
        twins.set("index.html.md", renderHomepageTwin(articles));
        twins.set("about.html.md", renderAboutTwin());

        assertNoBannedClaims(twins);

        for (const [relativePath, contents] of twins) {
          await writeFile(new URL(`./${relativePath}`, dir), contents, "utf8");
          logger.info(`markdown twin written: ${relativePath}`);
        }

        // Loud post-condition: every twin must actually be on disk in `dist/`.
        const onDisk = new Set([
          ...(await readdir(dir)).filter((name) => name.endsWith(".html.md")),
          ...(await readdir(new URL("./posts/", dir))).map((name) => `posts/${name}`),
        ]);
        const missing = [...twins.keys()].filter((relativePath) => !onDisk.has(relativePath));
        if (missing.length > 0) {
          throw new Error(
            `emitMarkdownTwins: ${missing.length} twin(s) missing from dist/: ${missing.join(", ")}`,
          );
        }

        logger.info(`markdown twins complete: ${twins.size} files (${EXPECTED_ARTICLES} posts + 2 pages)`);
      },
    },
  };
}